Trigger.script:
if tutorialState and tutorialState.isActive and not tutorialState.simulateConnection then local command = matches[2] or "" command = command:trim()
-- Skip empty commands or tutorial output if command == "" or command:starts("You ") or command:starts("The ") or command:starts("╔") or command:starts("║") or command:starts("Resolving") or command:starts("Connected") or command:starts("Loading") or command:starts("Character") or command:starts("Welcome") then return end
-- Process the command through tutorial system deleteLine() local response = mudletTutorial.processCommand(command) if response then cecho("" .. response .. "\n") end end
